import { test } from "node:test";
import assert from "node:assert/strict";
import { setImmediate as tick } from "node:timers/promises";
import { GatewayError, parseRetryAfter } from "../src/sms/errors.ts";
import { SmsSender, type SmsGateway, type SmsMessage } from "../src/sms/sender.ts";
import { sendReminders, type Reservation } from "../src/sms/reminders.ts";

// Fake time: sleep() records the delay and moves the clock forward instead of waiting.
function fakeTime(start = "2026-11-19T16:00:00Z") {
    const t = { now: new Date(start), slept: [] as number[] };
    const deps = {
        random: () => 0.5,
        async sleep(ms: number) {
            t.slept.push(ms);
            t.now = new Date(t.now.getTime() + ms);
            await tick();
        },
    };
    return { t, deps };
}

// Gateway fake: `respond` decides each call's outcome from the attempt number and the fake clock.
function gateway(respond: (call: number, msg: SmsMessage) => GatewayError | null): SmsGateway & { calls: SmsMessage[] } {
    const g = {
        calls: [] as SmsMessage[],
        async post(msg: SmsMessage) {
            g.calls.push(msg);
            await tick();
            const err = respond(g.calls.length, msg);
            if (err) throw err;
            return { messageId: `SM${g.calls.length}` };
        },
    };
    return g;
}

const msg: SmsMessage = { to: "+14155550123", body: "Your table is ready", idempotencyKey: "k1" };

test("Retry-After accepts seconds or an HTTP date", () => {
    const now = new Date("2026-11-19T16:00:00Z");
    assert.equal(parseRetryAfter("30", now), 30_000);
    assert.equal(parseRetryAfter("Thu, 19 Nov 2026 16:00:05 GMT", now), 5_000);
    assert.equal(parseRetryAfter(undefined, now), undefined);
});

test("server errors are retried with growing, jittered delays and the same idempotency key", async () => {
    const { t, deps } = fakeTime();
    const gw = gateway((call) => (call < 4 ? new GatewayError(503, "upstream carrier unavailable") : null));
    const id = await new SmsSender(gw, deps).send(msg);
    assert.equal(id, "SM4");
    assert.deepEqual(t.slept, [375, 750, 1500]);
    assert.deepEqual(new Set(gw.calls.map((c) => c.idempotencyKey)), new Set(["k1"]));
});

test("a rejected phone number is not retried", async () => {
    const { t, deps } = fakeTime();
    const gw = gateway(() => new GatewayError(400, "21211 invalid 'To' number"));
    await assert.rejects(new SmsSender(gw, deps).send(msg), /21211/);
    assert.equal(gw.calls.length, 1);
    assert.deepEqual(t.slept, []);
});

test("after the last attempt the gateway error is passed on", async () => {
    const { deps } = fakeTime();
    const gw = gateway(() => new GatewayError(502, "bad gateway"));
    await assert.rejects(new SmsSender(gw, deps, { maxAttempts: 3, baseDelayMs: 100, maxDelayMs: 1000 }).send(msg), /502/);
    assert.equal(gw.calls.length, 3);
});

test("when throttled, the next attempt waits at least as long as Retry-After says", async () => {
    const { t, deps } = fakeTime();
    const gw = gateway((call) => (call === 1 ? GatewayError.fromResponse(429, { "retry-after": "20" }, "too many requests", t.now) : null));
    await new SmsSender(gw, deps).send(msg);
    console.log("delays before each retry (ms):", t.slept);
    assert.equal(t.slept.length, 1);
    assert.ok(t.slept[0] >= 20_000, `retried after ${t.slept[0]}ms, gateway asked for 20000ms`);
});

test("a short Retry-After doesn't shrink the backoff below the usual step", async () => {
    const { t, deps } = fakeTime();
    const gw = gateway((call) => (call < 3 ? GatewayError.fromResponse(429, { "retry-after": "0" }, "slow down", t.now) : null));
    await new SmsSender(gw, deps).send(msg);
    assert.deepEqual(t.slept, [375, 750]);
});

test("reminders sent during a throttling window still go out once it ends", async () => {
    const { t, deps } = fakeTime();
    const throttledUntil = new Date("2026-11-19T16:00:10Z");
    const gw = gateway(() =>
        t.now < throttledUntil
            ? GatewayError.fromResponse(429, { "retry-after": throttledUntil.toUTCString() }, "account rate limit", t.now)
            : null,
    );
    const at = (h: number) => new Date(Date.UTC(2026, 10, 20, h));
    const reservations: Reservation[] = [
        { id: "r1", guestName: "Mia", phone: "+14155550101", restaurant: "Osteria Nove", partySize: 2, at: at(10) },
        { id: "r2", guestName: "Raj", phone: "+14155550102", restaurant: "Osteria Nove", partySize: 4, at: at(11) },
        { id: "r3", guestName: "Old", phone: "+14155550103", restaurant: "Osteria Nove", partySize: 2, at: new Date("2026-11-19T12:00:00Z") },
    ];
    const report = await sendReminders(new SmsSender(gw, deps), reservations, t.now);
    assert.deepEqual(report.failed, []);
    assert.deepEqual(report.sent, ["r1", "r2"]);
    assert.ok(gw.calls.filter((c) => c.idempotencyKey === "reminder:r1").length <= 2, "hammered the gateway while throttled");
});
